package com.zhou.craft.controller;
import com.zhou.craft.dto.ProfileForm;import com.zhou.craft.repo.*;import com.zhou.craft.security.AuthContext;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/profile")
public class ProfileController{private final UserRepository users;private final WorkFavoriteRepository favorites;private final CraftOrderRepository orders;private final CustomRequestRepository requests;
public ProfileController(UserRepository users,WorkFavoriteRepository favorites,CraftOrderRepository orders,CustomRequestRepository requests){this.users=users;this.favorites=favorites;this.orders=orders;this.requests=requests;}
@GetMapping public Map<String,Object> get(){var p=AuthContext.require();var u=users.findById(p.id()).orElseThrow();Map<String,Object>m=new LinkedHashMap<>();m.put("id",u.getId());m.put("username",u.getUsername());m.put("displayName",u.getDisplayName());m.put("email",u.getEmail());m.put("avatar",u.getAvatar());m.put("role",u.getRole());m.put("createdAt",u.getCreatedAt());m.put("favorites",favorites.findByUserIdOrderByCreatedAtDesc(u.getId()).size());m.put("orders",orders.findAll().stream().filter(o->Objects.equals(o.getCustomerId(),u.getId())).count());m.put("requests",requests.findAll().stream().filter(r->Objects.equals(r.getUserId(),u.getId())).count());return m;}
@PutMapping public Map<String,Object> update(@Valid @RequestBody ProfileForm f){var p=AuthContext.require();var u=users.findById(p.id()).orElseThrow();if(users.existsByEmail(f.email())&&!f.email().equalsIgnoreCase(u.getEmail()))throw new IllegalStateException("邮箱已被其他账号使用");u.updateProfile(f.displayName(),f.email(),f.avatar());users.save(u);return get();}}